    goto delete_parser;
  }

  done = (event.type == YAML_STREAM_END_EVENT);
  if (event_number >= MAX_EVENTS) {
    yaml_event_delete(&event);
    goto delete_parser;
  }

  if (copy_event(&events[event_number++], &event)) {
    yaml_event_delete(&event);
    goto delete_parser;
  }

  if (!yaml_emitter_emit(&emitter, &event)) {
    goto delete_parser;
  }

}

